import{_ as a,o as l,c as r,a3 as e}from"./chunks/framework.CTwvqqO-.js";const g=JSON.parse('{"title":"デイリースクラム","description":"デイリースクラム(Daily Scrum)の効果的な進行方法を段階別にご案内します。アジャイルチームの協力強化、進捗状況の点検、障害物解決のための15分会議の核心原則と実践ヒントをご確認ください。","frontmatter":{"title":"デイリースクラム","description":"デイリースクラム(Daily Scrum)の効果的な進行方法を段階別にご案内します。アジャイルチームの協力強化、進捗状況の点検、障害物解決のための15分会議の核心原則と実践ヒントをご確認ください。","head":[["meta",{"name":"keywords","content":"デイリースクラム, Daily Scrum, スクラム会議, アジャイル, アジャイル方法論, スクラムマスター, チームコラボレーション, 日次会議, スクラムの進め方, アジャイルコーチング, チームの障害解決"}],["meta",{"property":"og:title","content":"スクラムバン"}],["meta",{"property":"og:description","content":"デイリースクラム(Daily Scrum)の効果的な進行方法を段階別にご案内します。アジャイルチームの協力強化、進捗状況の点検、障害物解決のための15分会議の核心原則と実践ヒントをご確認ください。"}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://empasy.io/agile/activity.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/agile/dailyScrum.html"}]],"sort":3000},"headers":[],"relativePath":"ja/agile/dailyScrum.md","filePath":"ja/agile/dailyScrum.md","lastUpdated":1788749177000}'),i={name:"ja/agile/dailyScrum.md"};function o(n,t,s,d,h,c){return l(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="✅-デイリースクラムの進行方法" tabindex="-1">✅ デイリースクラムの進行方法 <a class="header-anchor" href="#✅-デイリースクラムの進行方法" aria-label="Permalink to “✅ デイリースクラムの進行方法”">​</a></h1><ol><li><strong>時間と場所の固定</strong></li></ol><ul><li>毎日同じ時間 (例：午前9時)</li><li>同じ場所 (会議室 または オンラインビデオ会議)</li></ul><ol start="2"><li><strong>参加者</strong></li></ol><ul><li>開発チーム全員 (開発者、QAなど)</li><li>スクラムマスター (進行補助)、POはオブザーバーとして参加可能</li></ul><ol start="3"><li><strong>進行方式</strong></li></ol><ul><li><p>時間は <strong>15分以内</strong></p></li><li><p>チームメンバーが <strong>順番に共有</strong></p></li><li><p><strong>3つの質問</strong>に合わせて簡潔に話す</p><ol><li>昨日何をしましたか？</li><li>今日は何をする予定ですか？</li><li>進行を妨げる障害物はありますか？</li></ol></li></ul><ol start="4"><li><strong>重要な原則</strong></li></ol><ul><li>詳細な技術的説明 ❌ → 「共有」中心</li><li>障害物はスクラム終了後に別途議論</li><li>報告ではなく <strong>チームの同期が目的</strong></li></ul><hr><h1 id="🎤-デイリースクラム-実際の進行例スクリプト" tabindex="-1">🎤 デイリースクラム 実際の進行例スクリプト <a class="header-anchor" href="#🎤-デイリースクラム-実際の進行例スクリプト" aria-label="Permalink to “🎤 デイリースクラム 実際の進行例スクリプト”">​</a></h1><h2 id="基本情報" tabindex="-1">基本情報 <a class="header-anchor" href="#基本情報" aria-label="Permalink to “基本情報”">​</a></h2><ul><li><strong>時間</strong>: 毎朝10:00 (15分以内)</li><li><strong>参加者</strong>: 開発チーム全体、スクラムマスター、必要に応じてプロダクトオーナー(PO)</li><li><strong>形式</strong>: 立ったまま進行 (リモート時はビデオ会議)</li></ul><hr><h2 id="_1-開始の挨拶および会議の目的の確認-2分" tabindex="-1">1. 開始の挨拶および会議の目的の確認 (2分) <a class="header-anchor" href="#_1-開始の挨拶および会議の目的の確認-2分" aria-label="Permalink to “1. 開始の挨拶および会議の目的の確認 (2分)”">​</a></h2><p><strong>スクラムマスター</strong>:</p><blockquote><p>「おはようございます。デイリースクラムを始めます。今日も各自、昨日やったこと、今日やること、そして障害要素があれば共有をお願いします。」</p></blockquote><hr><h2 id="_2-チームメンバー別の進捗状況の共有-10分" tabindex="-1">2. チームメンバー別の進捗状況の共有 (10分) <a class="header-anchor" href="#_2-チームメンバー別の進捗状況の共有-10分" aria-label="Permalink to “2. チームメンバー別の進捗状況の共有 (10分)”">​</a></h2><h3 id="開発のキムさん" tabindex="-1">開発のキムさん <a class="header-anchor" href="#開発のキムさん" aria-label="Permalink to “開発のキムさん”">​</a></h3><blockquote><p>「昨日はユーザーログインAPIの開発を完了しました。今日はユーザープロフィール照会機能を実装する予定です。現在、特に障害要素はありません。」</p></blockquote><h3 id="デザインのイさん" tabindex="-1">デザインのイさん <a class="header-anchor" href="#デザインのイさん" aria-label="Permalink to “デザインのイさん”">​</a></h3><blockquote><p>「昨日は決済ページのUIデザインを完了し、開発チームに引き渡しました。今日は管理者ページのデザインを開始する予定です。ただ、開発パートとの協議が必要な部分があるので、午後に短くミーティングをお願いできますか？」</p></blockquote><p><strong>スクラムマスター</strong>:</p><blockquote><p>「はい、会議後に関連チームメンバーとスケジュールを調整します。」</p></blockquote><h3 id="バックエンドのパクさん" tabindex="-1">バックエンドのパクさん <a class="header-anchor" href="#バックエンドのパクさん" aria-label="Permalink to “バックエンドのパクさん”">​</a></h3><blockquote><p>「昨日はDB最適化作業を行い、今日はパフォーマンステストを行う予定です。ただ、テストサーバーのCPU使用率が高いので、モニタリングが必要だと思います。」</p></blockquote><p><strong>スクラムマスター</strong>:</p><blockquote><p>「障害要素として記録しておき、会議後にインフラチームと協議してみます。」</p></blockquote><h3 id="qaのチョンさん" tabindex="-1">QAのチョンさん <a class="header-anchor" href="#qaのチョンさん" aria-label="Permalink to “QAのチョンさん”">​</a></h3><blockquote><p>「昨日はログイン機能のテストを完了し、今日は新たに追加された決済機能のテストを開始する予定です。テストシナリオの中で開発チームの確認が必要な部分がいくつかあります。」</p></blockquote><p><strong>スクラムマスター</strong>:</p><blockquote><p>「会議後にすぐに関連開発者とお繋ぎします。」</p></blockquote><hr><h2 id="_3-障害要素の要約および対応計画の策定-2分" tabindex="-1">3. 障害要素の要約および対応計画の策定 (2分) <a class="header-anchor" href="#_3-障害要素の要約および対応計画の策定-2分" aria-label="Permalink to “3. 障害要素の要約および対応計画の策定 (2分)”">​</a></h2><p><strong>スクラムマスター</strong>:</p><blockquote><p>「これまでに共有された障害要素をまとめると：</p><ol><li>デザインと開発の協議ミーティングが必要</li><li>テストサーバーのCPU使用率の問題</li><li>QAテストシナリオの確認が必要</li></ol><p>この3つの項目について、私が各担当者と調整します。」</p></blockquote><hr><h2 id="_4-会議の終了-1分" tabindex="-1">4. 会議の終了 (1分) <a class="header-anchor" href="#_4-会議の終了-1分" aria-label="Permalink to “4. 会議の終了 (1分)”">​</a></h2><p><strong>スクラムマスター</strong>:</p><blockquote><p>「皆さん、今日のやるべきことが明確になり、障害要素も把握できました。会議はここで終了し、必要な方は別途議論を続けてください。皆さん、今日も頑張りましょう！」</p></blockquote><hr><h2 id="デイリースクラムの効果的な運用ヒント" tabindex="-1">デイリースクラムの効果的な運用ヒント <a class="header-anchor" href="#デイリースクラムの効果的な運用ヒント" aria-label="Permalink to “デイリースクラムの効果的な運用ヒント”">​</a></h2><ul><li><strong>時間厳守</strong>: 15分のルールを守るため、立ったままでの会議を推奨</li><li><strong>問題解決会議の禁止</strong>: 深い議論は別途時間を確保して進行</li><li><strong>全チームメンバーの参加</strong>: 満遍なく発言できるように雰囲気作り</li><li><strong>視覚的な補助ツールの活用</strong>: カンバンボード、タスク管理ツールなどを併用</li><li><strong>障害要素への集中</strong>: 問題解決のためのアクションプランを必ず策定</li></ul><hr><h2 id="記録の例" tabindex="-1">記録の例 <a class="header-anchor" href="#記録の例" aria-label="Permalink to “記録の例”">​</a></h2><table tabindex="0"><thead><tr><th>担当者</th><th>昨日やったこと</th><th>今日やること</th><th>障害要素</th></tr></thead><tbody><tr><td>開発キム</td><td>ログインAPI開発完了</td><td>プロフィール照会機能実装</td><td>なし</td></tr><tr><td>デザインイ</td><td>決済ページUI完了</td><td>管理者ページデザイン開始</td><td>開発チームと協議が必要</td></tr><tr><td>バックエンドパク</td><td>DB最適化作業</td><td>パフォーマンステスト進行</td><td>テストサーバーCPU使用率問題</td></tr><tr><td>QAチョン</td><td>ログイン機能テスト完了</td><td>決済機能テスト開始</td><td>テストシナリオの確認が必要</td></tr></tbody></table><hr><h1 id="✅-デイリースクラム進行用チェックリスト" tabindex="-1">✅ デイリースクラム進行用チェックリスト <a class="header-anchor" href="#✅-デイリースクラム進行用チェックリスト" aria-label="Permalink to “✅ デイリースクラム進行用チェックリスト”">​</a></h1><h2 id="📌-進行者-スクラムマスター-チェックリスト" tabindex="-1">📌 進行者(スクラムマスター)チェックリスト <a class="header-anchor" href="#📌-進行者-スクラムマスター-チェックリスト" aria-label="Permalink to “📌 進行者(スクラムマスター)チェックリスト”">​</a></h2><ul><li>[ ] 毎日同じ時間/場所(あるいはオンライン)で開始したか？</li><li>[ ] 15分以内で終わらせる準備ができているか？</li><li>[ ] 各チームメンバーが <strong>昨日/今日/障害物</strong> の3項目だけを共有するように誘導したか？</li><li>[ ] 共有された <strong>障害物(Blocking Issue)</strong> は別途Follow-upとして記録したか？</li><li>[ ] スクラム終了後、課題解決のための追加ミーティングが必要な人だけを招集したか？</li></ul><hr><h2 id="📌-チームメンバー個別の共有チェックリスト" tabindex="-1">📌 チームメンバー個別の共有チェックリスト <a class="header-anchor" href="#📌-チームメンバー個別の共有チェックリスト" aria-label="Permalink to “📌 チームメンバー個別の共有チェックリスト”">​</a></h2><ul><li>[ ] 昨日私が完了したことは？</li><li>[ ] 今日私がやるべきことは？</li><li>[ ] 進行を妨げる障害物はあるか？</li></ul><p>👉 共有は <strong>短く明確に (1〜2文)</strong> 👉 問題解決の議論は ❌ (スクラムの後に別途)</p><hr><h2 id="チームメンバー共有例のテンプレート" tabindex="-1">チームメンバー共有例のテンプレート <a class="header-anchor" href="#チームメンバー共有例のテンプレート" aria-label="Permalink to “チームメンバー共有例のテンプレート”">​</a></h2><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[名前]</span></span>
<span class="line"><span>- 昨日:</span></span>
<span class="line"><span>- 今日:</span></span>
<span class="line"><span>- 障害物:</span></span></code></pre></div><hr><h2 id="📊-チーム全体のスクラムボード例-ホワイトボード-オンラインコラボレーションツール" tabindex="-1">📊 チーム全体のスクラムボード例 (ホワイトボード / オンラインコラボレーションツール) <a class="header-anchor" href="#📊-チーム全体のスクラムボード例-ホワイトボード-オンラインコラボレーションツール" aria-label="Permalink to “📊 チーム全体のスクラムボード例 (ホワイトボード / オンラインコラボレーションツール)”">​</a></h2><table tabindex="0"><thead><tr><th>名前</th><th>昨日やったこと</th><th>今日やること</th><th>障害物 (Blocking Issue)</th></tr></thead><tbody><tr><td>チョルス</td><td>ログインAPIリファクタリング完了</td><td>Googleソーシャルログイン連携開始</td><td>Google OAuthドキュメントにアクセス不可</td></tr><tr><td>ヨンヒ</td><td>会員登録機能のテストケース作成と一部実行</td><td>会員登録機能全体のテストとバグレポート</td><td>テストサーバーが頻繁に切断される</td></tr><tr><td>ミンス</td><td>ダッシュボードUI作業</td><td>チャートライブラリの適用とAPI連携</td><td>最新API仕様書が共有されていない</td></tr></tbody></table><hr><p>👉 このようにすれば、チームメンバーは毎日 <strong>チェックリストに基づいて話すだけでよく</strong>、スクラムマスターは <strong>テーブルを更新するだけ</strong> で記録と共有が同時に解決します。</p><hr>`,64)])])}const b=a(i,[["render",o]]);export{g as __pageData,b as default};
